    w.heading('Data and code availability');w.para('Regional input subsets, source-specific provenance, analysis scripts and reference outputs are retained in the Thailand water-storage repository at https://github.com/pratikkhanal16/thailand-water-storage-dss . The extended CSR-based study is versioned separately from earlier analyses. Original dataset notices and the noncommercial GROW package terms accompany the inputs. Numerical reproduction does not establish causal human depletion.')
    w.heading('Acknowledgment');w.para('Academic supervision is acknowledged to Dr. Natthachet Tangdamrongsub, Asian Institute of Technology. Data providers are acknowledged through the cited products.')
    w.heading('References',1)
    for ref in M.REFS:
        p=w.para(ref,size=10.5,spacing=1.1,after=6,align=M.WD_ALIGN_PARAGRAPH.LEFT);p.paragraph_format.left_indent=M.Inches(.25);p.paragraph_format.first_line_indent=M.Inches(-.25)
    w.save(OUT/'manuscript/Manuscript_Attribution_Credibility_Farzeen_Khan.docx')
    (OUT/'logs/manuscript_content.json').write_text(json.dumps({'title':M.PAPER_TITLE,'author':M.AUTHOR,'abstract':M.ABSTRACT,'introduction':INTRO,'methods':METHODS,'results':RESULTS,'discussion':DISCUSSION,'conclusion':CONCLUSION,'references':M.REFS},indent=2,ensure_ascii=False),encoding='utf-8')
